window.ORACLE_ANSWERS = [{"id":1,"zh":"先迈出你能承担的那一步。","en":"Take the first step you can manage.","category":"action"},{"id":2,"zh":"把想法变成一个小小的试验。","en":"Turn your idea into a small experiment.","category":"action"},{"id":3,"zh":"今天就把开头写下来。","en":"Write the beginning today.","category":"action"},{"id":4,"zh":"带着一点紧张出发也可以。","en":"You can begin while feeling a little nervous.","category":"action"},{"id":5,"zh":"把请求说得具体一点。","en":"Make your request more specific.","category":"action"},{"id":6,"zh":"试着主动发出一次邀请。","en":"Try being the one to extend an invitation.","category":"action"},{"id":7,"zh":"先完成，再慢慢打磨。","en":"Finish it first; polish it afterward.","category":"action"},{"id":8,"zh":"给这件事一个真正的开始。","en":"Give this a real beginning.","category":"action"},{"id":9,"zh":"从你最熟悉的部分动手。","en":"Start with the part you know best.","category":"action"},{"id":10,"zh":"把困难拆成今天能做的一件事。","en":"Break the challenge into one thing you can do today.","category":"action"},{"id":11,"zh":"换一种说法，再试一次。","en":"Rephrase it and try again.","category":"action"},{"id":12,"zh":"让行动替你回答一部分疑问。","en":"Let action answer some of your questions.","category":"action"},{"id":13,"zh":"主动争取一个反馈的机会。","en":"Seek a chance to get feedback.","category":"action"},{"id":14,"zh":"允许自己做一个不熟练的新手。","en":"Allow yourself to be an inexperienced beginner.","category":"action"},{"id":15,"zh":"把重要的话亲口说出来。","en":"Say the important words yourself.","category":"action"},{"id":16,"zh":"为这次尝试留一个出口。","en":"Leave yourself a way out of this attempt.","category":"action"},{"id":17,"zh":"选一个安静的地方开始。","en":"Find a quiet place to begin.","category":"action"},{"id":18,"zh":"拿出一份可以讨论的草稿。","en":"Make a draft that others can respond to.","category":"action"},{"id":19,"zh":"先做十分钟看看。","en":"Try working on it for ten minutes.","category":"action"},{"id":20,"zh":"你的下一步可以很小。","en":"Your next step can be small.","category":"action"},{"id":21,"zh":"先把最麻烦的准备做好。","en":"Get the trickiest preparation out of the way.","category":"action"},{"id":22,"zh":"走出熟悉的路线一次。","en":"Take an unfamiliar route for once.","category":"action"},{"id":23,"zh":"把愿望排进日程。","en":"Put your wish on the calendar.","category":"action"},{"id":24,"zh":"争取你需要的资源。","en":"Ask for the resources you need.","category":"action"},{"id":25,"zh":"用一次练习代替反复设想。","en":"Replace repeated imagining with one practice run.","category":"action"},{"id":26,"zh":"把选择权拿回自己手中。","en":"Reclaim your right to choose.","category":"action"},{"id":27,"zh":"这次可以由你先开口。","en":"This time, you can speak first.","category":"action"},{"id":28,"zh":"认真提出你的不同意见。","en":"State your disagreement thoughtfully.","category":"action"},{"id":29,"zh":"把边界说清楚，事情才能继续。","en":"Clarify your boundaries so things can move forward.","category":"action"},{"id":30,"zh":"问一个你一直不好意思问的问题。","en":"Ask the question you have been too shy to ask.","category":"action"},{"id":31,"zh":"试一个成本更低的版本。","en":"Try a less costly version.","category":"action"},{"id":32,"zh":"带上准备，而非所有答案。","en":"Bring preparation; you need not have every answer.","category":"action"},{"id":33,"zh":"给好点子一个落地的机会。","en":"Give a good idea a chance to become real.","category":"action"},{"id":34,"zh":"接受帮助，也是一种行动。","en":"Accepting help is a way forward too.","category":"action"},{"id":35,"zh":"去做那件已经准备好的事。","en":"Do the thing you are already prepared for.","category":"action"},{"id":36,"zh":"把答应的那一步落实。","en":"Follow through on the step you promised.","category":"action"},{"id":37,"zh":"先修好眼前这个小问题。","en":"Fix the small problem in front of you first.","category":"action"},{"id":38,"zh":"为自己争取一次公平的机会。","en":"Ask for a fair chance.","category":"action"},{"id":39,"zh":"试着用更直接的方式沟通。","en":"Try communicating more directly.","category":"action"},{"id":40,"zh":"让你的作品先见见光。","en":"Let someone see your work.","category":"action"},{"id":41,"zh":"把今天的精力放在一个重点上。","en":"Give your energy to one priority today.","category":"action"},{"id":42,"zh":"给自己安排一次没有观众的练习。","en":"Practice once without an audience.","category":"action"},{"id":43,"zh":"改掉最妨碍你的那个小习惯。","en":"Change the small habit that gets in your way most.","category":"action"},{"id":44,"zh":"先建立一个可以坚持的节奏。","en":"Build a rhythm you can sustain.","category":"action"},{"id":45,"zh":"把好奇心变成一个问题。","en":"Turn your curiosity into a question.","category":"action"},{"id":46,"zh":"找个伙伴，一起完成第一步。","en":"Find a partner for the first step.","category":"action"},{"id":47,"zh":"把你能负责的部分做好。","en":"Do your part with care.","category":"action"},{"id":48,"zh":"试着把标准说给别人听。","en":"Try explaining your standards to someone else.","category":"action"},{"id":49,"zh":"为想做的事腾出一点空间。","en":"Make some room for what you want to do.","category":"action"},{"id":50,"zh":"亲自确认那个一直悬着的细节。","en":"Check that lingering detail yourself.","category":"action"},{"id":51,"zh":"给一次失败留出重新尝试的余地。","en":"Leave room to try again after a setback.","category":"action"},{"id":52,"zh":"把担心写成一份准备清单。","en":"Turn your worries into a preparation checklist.","category":"action"},{"id":53,"zh":"这次试着坚定地说完。","en":"Try finishing what you want to say with confidence.","category":"action"},{"id":54,"zh":"先把门敲响。","en":"Knock on the door first.","category":"action"},{"id":55,"zh":"你可以请求一次重新讨论。","en":"You can ask to reopen the discussion.","category":"action"},{"id":56,"zh":"把注意力放回手上的事情。","en":"Bring your attention back to the task at hand.","category":"action"},{"id":57,"zh":"用你已有的条件开始。","en":"Begin with what you already have.","category":"action"},{"id":58,"zh":"把一个拖延的承诺兑现。","en":"Keep a promise you have been putting off.","category":"action"},{"id":59,"zh":"今天为明天减少一个障碍。","en":"Remove one obstacle today for tomorrow.","category":"action"},{"id":60,"zh":"为自己的努力留下记录。","en":"Keep a record of your efforts.","category":"action"},{"id":61,"zh":"试着做一件平时会回避的小事。","en":"Try one small thing you usually avoid.","category":"action"},{"id":62,"zh":"先让最重要的人听懂。","en":"Help the person who matters most understand first.","category":"action"},{"id":63,"zh":"用一个具体的例子表达立场。","en":"Explain your position with a concrete example.","category":"action"},{"id":64,"zh":"把练习当作今天的成果。","en":"Let practice be today's achievement.","category":"action"},{"id":65,"zh":"去一个能认真工作的地方。","en":"Go somewhere you can focus on the work.","category":"action"},{"id":66,"zh":"把散乱的念头整理成三句话。","en":"Gather your scattered thoughts into three sentences.","category":"action"},{"id":67,"zh":"给自己的决定配上一个行动。","en":"Pair your decision with an action.","category":"action"},{"id":68,"zh":"把你希望发生的变化说出来。","en":"Name the change you hope to see.","category":"action"},{"id":69,"zh":"先把可以撤回的一步走完。","en":"Take the reversible step first.","category":"action"},{"id":70,"zh":"用一次真诚的尝试结束犹豫。","en":"End the hesitation with an honest attempt.","category":"action"},{"id":71,"zh":"今晚先不作决定。","en":"Leave the decision until after tonight.","category":"patience"},{"id":72,"zh":"让最初的兴奋过去再看。","en":"Reconsider after the first rush of excitement fades.","category":"patience"},{"id":73,"zh":"给事情一点自然展开的时间。","en":"Give things time to unfold.","category":"patience"},{"id":74,"zh":"先睡个好觉，再回答。","en":"Get a good night's sleep before answering.","category":"patience"},{"id":75,"zh":"别在疲惫时给自己下结论。","en":"Do not judge yourself when you are tired.","category":"patience"},{"id":76,"zh":"这一步值得慢一点。","en":"This step deserves a slower pace.","category":"patience"},{"id":77,"zh":"等双方都能好好听的时候再谈。","en":"Talk when both of you are ready to listen.","category":"patience"},{"id":78,"zh":"现在适合整理，未必适合推进。","en":"Now may be better for organizing than moving ahead.","category":"patience"},{"id":79,"zh":"让答案沉淀一晚。","en":"Let the answer settle overnight.","category":"patience"},{"id":80,"zh":"暂时把这个问题放在一边。","en":"Set this question aside for a while.","category":"patience"},{"id":81,"zh":"你不必立刻回复每一个请求。","en":"You do not need to answer every request immediately.","category":"patience"},{"id":82,"zh":"给自己一个明确的等待期限。","en":"Set a clear limit on how long you will wait.","category":"patience"},{"id":83,"zh":"进展缓慢，也可能正在积累。","en":"Slow progress may still be building something.","category":"patience"},{"id":84,"zh":"等关键条件到位。","en":"Wait for the key conditions to be in place.","category":"patience"},{"id":85,"zh":"先照顾好今天的精力。","en":"Take care of today's energy first.","category":"patience"},{"id":86,"zh":"有些话适合明天再说。","en":"Some words are better saved for tomorrow.","category":"patience"},{"id":87,"zh":"不要催促一个还在形成的想法。","en":"Do not rush an idea that is still taking shape.","category":"patience"},{"id":88,"zh":"留出时间看清自己的感受。","en":"Make time to understand how you feel.","category":"patience"},{"id":89,"zh":"先让情绪从最满的地方退下来。","en":"Let the strongest feelings ease first.","category":"patience"},{"id":90,"zh":"重复检查未必能让结果更快。","en":"Checking again may not make the result arrive sooner.","category":"patience"},{"id":91,"zh":"暂停一下，听听周围的声音。","en":"Pause and listen to what is around you.","category":"patience"},{"id":92,"zh":"这段空白可以暂时留着。","en":"You can leave this blank for now.","category":"patience"},{"id":93,"zh":"别把别人的进度当作你的时钟。","en":"Do not let someone else's progress set your pace.","category":"patience"},{"id":94,"zh":"慢下来，看看自己遗漏了什么。","en":"Slow down and see what you may have missed.","category":"patience"},{"id":95,"zh":"等待期间，也可以照常生活。","en":"You can keep living while you wait.","category":"patience"},{"id":96,"zh":"给对方一些消化的时间。","en":"Give the other person time to take it in.","category":"patience"},{"id":97,"zh":"这件事不需要在今天完成。","en":"This does not have to be finished today.","category":"patience"},{"id":98,"zh":"先停在一个安全的位置。","en":"Pause somewhere safe first.","category":"patience"},{"id":99,"zh":"等承诺变成行动再往前。","en":"Wait for the promise to become action before proceeding.","category":"patience"},{"id":100,"zh":"留一点不安排的时间。","en":"Leave some time unplanned.","category":"patience"},{"id":101,"zh":"先休息，努力可以稍后继续。","en":"Rest first; the effort can continue later.","category":"patience"},{"id":102,"zh":"让新习惯长稳，再增加难度。","en":"Let the new habit settle before making it harder.","category":"patience"},{"id":103,"zh":"把紧迫感和真正的期限分开。","en":"Separate the feeling of urgency from the actual deadline.","category":"patience"},{"id":104,"zh":"你可以晚一点给出最终答案。","en":"You can give your final answer a little later.","category":"patience"},{"id":105,"zh":"不妨过几天再读一遍。","en":"Try reading it again in a few days.","category":"patience"},{"id":106,"zh":"让一次见面留下回想的空间。","en":"Leave room to reflect after a meeting.","category":"patience"},{"id":107,"zh":"别急着填满每一次沉默。","en":"Do not rush to fill every silence.","category":"patience"},{"id":108,"zh":"先把呼吸放缓。","en":"Slow your breathing first.","category":"patience"},{"id":109,"zh":"今天适合收尾。","en":"Today is a good day to wrap things up.","category":"patience"},{"id":110,"zh":"留出适应新变化的时间。","en":"Allow time to adjust to the change.","category":"patience"},{"id":111,"zh":"不确定的时候，可以先保持现状。","en":"When uncertain, you can keep things as they are for now.","category":"patience"},{"id":112,"zh":"等你能平静描述它时，再讨论。","en":"Discuss it when you can describe it calmly.","category":"patience"},{"id":113,"zh":"给一次尝试足够的观察时间。","en":"Give an attempt enough time to show you something.","category":"patience"},{"id":114,"zh":"你需要的可能只是一次间歇。","en":"What you need may simply be a break.","category":"patience"},{"id":115,"zh":"别把暂时的停顿当成终点。","en":"Do not mistake a temporary pause for the end.","category":"patience"},{"id":116,"zh":"先结束今天，再计划下一程。","en":"Finish today before planning the next stretch.","category":"patience"},{"id":117,"zh":"没有新信息时，不必反复重算。","en":"Without new information, you need not keep reconsidering.","category":"patience"},{"id":118,"zh":"时间留得宽一点，心会更稳。","en":"Allowing more time can help you feel steadier.","category":"patience"},{"id":119,"zh":"等现实给出下一条线索。","en":"Wait for the next clue from what actually happens.","category":"patience"},{"id":120,"zh":"这次让耐心多留一会儿。","en":"Give patience a little more room this time.","category":"patience"},{"id":121,"zh":"把长远的事放回长远的尺度。","en":"Give long-term matters a long-term perspective.","category":"patience"},{"id":122,"zh":"你可以先观察，不必马上加入。","en":"You can observe before joining in.","category":"patience"},{"id":123,"zh":"让已经做出的努力发挥作用。","en":"Give the effort you have made time to work.","category":"patience"},{"id":124,"zh":"不是每个念头都需要立刻回应。","en":"Not every thought needs an immediate response.","category":"patience"},{"id":125,"zh":"先走完这一段，再看下一段。","en":"Finish this stretch before looking at the next.","category":"patience"},{"id":126,"zh":"别为提前到来的担忧赶路。","en":"Do not hurry for worries that arrived too early.","category":"patience"},{"id":127,"zh":"把等待变成准备的时间。","en":"Use the waiting time to prepare.","category":"patience"},{"id":128,"zh":"停下来，也能看见新的路。","en":"Pausing can reveal another path.","category":"patience"},{"id":129,"zh":"给熟悉的事一次重新理解的机会。","en":"Give something familiar a chance to mean something new.","category":"patience"},{"id":130,"zh":"下一次出发前，先补足力气。","en":"Recover your strength before setting out again.","category":"patience"},{"id":131,"zh":"你还需要一条可靠的信息。","en":"You need one more reliable piece of information.","category":"judgment"},{"id":132,"zh":"先确认你们说的是同一件事。","en":"Check that you are talking about the same thing.","category":"judgment"},{"id":133,"zh":"把事实和猜测分别写下来。","en":"Write down facts and guesses separately.","category":"judgment"},{"id":134,"zh":"看看这个决定的日常成本。","en":"Look at the everyday cost of this decision.","category":"judgment"},{"id":135,"zh":"问问真正做过这件事的人。","en":"Ask someone who has actually done this.","category":"judgment"},{"id":136,"zh":"先读清楚条件。","en":"Read the conditions carefully first.","category":"judgment"},{"id":137,"zh":"找出最容易被忽略的限制。","en":"Identify the constraint that is easiest to overlook.","category":"judgment"},{"id":138,"zh":"你是否把愿望当成了证据？","en":"Are you treating a wish as evidence?","category":"judgment"},{"id":139,"zh":"先核对消息来自哪里。","en":"Check where the information came from.","category":"judgment"},{"id":140,"zh":"想想最普通的结果，而非最理想的。","en":"Consider the ordinary outcome, not just the ideal one.","category":"judgment"},{"id":141,"zh":"比较具体细节，别只比较感觉。","en":"Compare the details as well as your impressions.","category":"judgment"},{"id":142,"zh":"弄清楚谁来承担后果。","en":"Clarify who will bear the consequences.","category":"judgment"},{"id":143,"zh":"先问一句：还有别的解释吗？","en":"First ask: could there be another explanation?","category":"judgment"},{"id":144,"zh":"你可能漏掉了一个更简单的选项。","en":"You may have missed a simpler option.","category":"judgment"},{"id":145,"zh":"把问题缩小，答案会更清楚。","en":"Narrow the question for a clearer answer.","category":"judgment"},{"id":146,"zh":"查看实际发生过什么。","en":"Look at what has actually happened.","category":"judgment"},{"id":147,"zh":"别让最响亮的意见占满桌面。","en":"Make room for more than the loudest opinion.","category":"judgment"},{"id":148,"zh":"这件事的关键藏在执行里。","en":"The key lies in how this will be carried out.","category":"judgment"},{"id":149,"zh":"先算清你能投入多少时间。","en":"Work out how much time you can give.","category":"judgment"},{"id":150,"zh":"留意没有被说出口的条件。","en":"Notice the conditions that have gone unspoken.","category":"judgment"},{"id":151,"zh":"问清楚完成的标准。","en":"Ask what counts as finished.","category":"judgment"},{"id":152,"zh":"换一个角度检查你的假设。","en":"Examine your assumptions from another angle.","category":"judgment"},{"id":153,"zh":"先验证最不确定的那一环。","en":"Test the least certain part first.","category":"judgment"},{"id":154,"zh":"一个鲜明的例子不代表全部。","en":"One striking example does not tell the whole story.","category":"judgment"},{"id":155,"zh":"看看有没有更近的解决办法。","en":"Look for a solution closer at hand.","category":"judgment"},{"id":156,"zh":"把真正的问题用一句话说清楚。","en":"State the real problem in one sentence.","category":"judgment"},{"id":157,"zh":"区分你能改变的和不能改变的。","en":"Distinguish what you can change from what you cannot.","category":"judgment"},{"id":158,"zh":"先了解退出的条件。","en":"Understand the exit conditions first.","category":"judgment"},{"id":159,"zh":"你需要听听不赞同你的理由。","en":"You need to hear the reasons for disagreement.","category":"judgment"},{"id":160,"zh":"留意连续发生的小信号。","en":"Notice the small signals that keep recurring.","category":"judgment"},{"id":161,"zh":"先看长期是否维持得住。","en":"Check whether it can be sustained over time.","category":"judgment"},{"id":162,"zh":"细节不清楚，就再问一次。","en":"If the details are unclear, ask again.","category":"judgment"},{"id":163,"zh":"把所有选项放到同一标准下。","en":"Compare all options using the same criteria.","category":"judgment"},{"id":164,"zh":"确认这个问题是否真的需要解决。","en":"Check whether this problem actually needs solving.","category":"judgment"},{"id":165,"zh":"不要用一次失误概括一个人。","en":"Do not define someone by a single mistake.","category":"judgment"},{"id":166,"zh":"问问自己最在意哪一项。","en":"Ask yourself which part matters most.","category":"judgment"},{"id":167,"zh":"你得到的是承诺，还是已经有的结果？","en":"Do you have a promise, or an actual result?","category":"judgment"},{"id":168,"zh":"找出那个会改变结论的条件。","en":"Identify the condition that would change your conclusion.","category":"judgment"},{"id":169,"zh":"先查看原始记录。","en":"Check the original record first.","category":"judgment"},{"id":170,"zh":"把复杂的计划讲给外行听听。","en":"Explain the complicated plan to someone new to it.","category":"judgment"},{"id":171,"zh":"有些分歧来自不同的定义。","en":"Some disagreements come from different definitions.","category":"judgment"},{"id":172,"zh":"注意你的判断受谁的情绪影响。","en":"Notice whose emotions are influencing your judgment.","category":"judgment"},{"id":173,"zh":"先问需求，再选方法。","en":"Understand the need before choosing the method.","category":"judgment"},{"id":174,"zh":"看看最坏情况是否可以承受。","en":"Consider whether you could handle the worst outcome.","category":"judgment"},{"id":175,"zh":"不要让已经投入的时间替你决定。","en":"Do not let time already spent decide for you.","category":"judgment"},{"id":176,"zh":"把未来一周的生活想具体些。","en":"Picture the coming week in practical detail.","category":"judgment"},{"id":177,"zh":"先找到可以核实的部分。","en":"Start with what can be checked.","category":"judgment"},{"id":178,"zh":"留意你一直避而不谈的那个点。","en":"Notice the point you keep avoiding.","category":"judgment"},{"id":179,"zh":"把好看和好用分开评价。","en":"Assess appearance and usefulness separately.","category":"judgment"},{"id":180,"zh":"多一个选项，可能就不必勉强。","en":"Another option may spare you a forced choice.","category":"judgment"},{"id":181,"zh":"先查清这一条规则的适用范围。","en":"Check when this rule actually applies.","category":"judgment"},{"id":182,"zh":"你的标准需要一致。","en":"Your criteria need to be consistent.","category":"judgment"},{"id":183,"zh":"试着替相反的选择说一句话。","en":"Try making one argument for the opposite choice.","category":"judgment"},{"id":184,"zh":"确认你拥有作决定的权限。","en":"Make sure the decision is yours to make.","category":"judgment"},{"id":185,"zh":"比较结果，也比较过程。","en":"Compare the process as well as the outcome.","category":"judgment"},{"id":186,"zh":"看看这个方案需要谁配合。","en":"Check whose cooperation this plan requires.","category":"judgment"},{"id":187,"zh":"把例外情况也算进去。","en":"Take the exceptions into account too.","category":"judgment"},{"id":188,"zh":"问一个能得到具体回答的问题。","en":"Ask a question that invites a specific answer.","category":"judgment"},{"id":189,"zh":"先了解现有办法为什么失效。","en":"Find out why the current approach is not working.","category":"judgment"},{"id":190,"zh":"检查你是否在回答另一个问题。","en":"Check that you are answering the right question.","category":"judgment"},{"id":191,"zh":"可以，前提是你愿意承担这一份责任。","en":"Yes, if you are willing to take that responsibility.","category":"direction"},{"id":192,"zh":"现在先不要答应。","en":"Do not say yes just yet.","category":"direction"},{"id":193,"zh":"这一次，值得试试。","en":"This is worth trying once.","category":"direction"},{"id":194,"zh":"如果只能勉强维持，就先放下。","en":"If it barely holds together, set it aside for now.","category":"direction"},{"id":195,"zh":"保留这个选择。","en":"Keep this option open.","category":"direction"},{"id":196,"zh":"你可以拒绝这个额外要求。","en":"You can decline this extra request.","category":"direction"},{"id":197,"zh":"条件谈清楚以后，再继续。","en":"Continue once the terms are clear.","category":"direction"},{"id":198,"zh":"这个方向可以继续探索。","en":"You can keep exploring this direction.","category":"direction"},{"id":199,"zh":"暂时不适合扩大规模。","en":"This is not the time to scale up.","category":"direction"},{"id":200,"zh":"愿意长期投入，就给它一个机会。","en":"Give it a chance if you are willing to stay committed.","category":"direction"},{"id":201,"zh":"不要为了合群而同意。","en":"Do not agree just to fit in.","category":"direction"},{"id":202,"zh":"先选更容易撤回的那个。","en":"Choose the more reversible option first.","category":"direction"},{"id":203,"zh":"这不是你必须接下的任务。","en":"This is not a task you have to accept.","category":"direction"},{"id":204,"zh":"有明确支持时，可以往前一步。","en":"With clear support, you can take a step forward.","category":"direction"},{"id":205,"zh":"值得认真谈一次。","en":"It deserves a serious conversation.","category":"direction"},{"id":206,"zh":"把这项承诺减半再考虑。","en":"Consider it again with half the commitment.","category":"direction"},{"id":207,"zh":"如果需要隐瞒重要事实，就不要。","en":"If it requires hiding important facts, say no.","category":"direction"},{"id":208,"zh":"你已经可以结束这次尝试。","en":"You can bring this attempt to a close.","category":"direction"},{"id":209,"zh":"优先选能让日常更轻松的办法。","en":"Favor the approach that makes everyday life easier.","category":"direction"},{"id":210,"zh":"这件事值得你留出时间。","en":"This deserves a place in your schedule.","category":"direction"},{"id":211,"zh":"先不要改变已经有效的部分。","en":"Leave the parts that work as they are for now.","category":"direction"},{"id":212,"zh":"如果双方都愿意，可以重新开始。","en":"You can begin again if both of you want to.","category":"direction"},{"id":213,"zh":"把机会留给更合适的事情。","en":"Leave room for something that fits better.","category":"direction"},{"id":214,"zh":"可以接受，但不必照单全收。","en":"You can accept it without accepting every part.","category":"direction"},{"id":215,"zh":"不要跨过你已经明确的底线。","en":"Do not cross a boundary you have clearly set.","category":"direction"},{"id":216,"zh":"小范围尝试，比全面投入更合适。","en":"A limited trial is more suitable than a full commitment.","category":"direction"},{"id":217,"zh":"这次选择简单一点。","en":"Choose something simpler this time.","category":"direction"},{"id":218,"zh":"如果目标已经不同，就调整路线。","en":"If the goal has changed, adjust your route.","category":"direction"},{"id":219,"zh":"你不需要再证明这一点。","en":"You do not need to prove this again.","category":"direction"},{"id":220,"zh":"这个邀请可以认真考虑。","en":"This invitation is worth considering.","category":"direction"},{"id":221,"zh":"只有获得同意，才继续下一步。","en":"Proceed only with consent.","category":"direction"},{"id":222,"zh":"答案可以是：今天不行。","en":"Your answer can be: not today.","category":"direction"},{"id":223,"zh":"在能力范围内，可以伸出援手。","en":"You can help within your capacity.","category":"direction"},{"id":224,"zh":"不要为避免尴尬而作承诺。","en":"Do not make a promise just to avoid awkwardness.","category":"direction"},{"id":225,"zh":"把最有把握的选项放在前面。","en":"Put the option you trust most first.","category":"direction"},{"id":226,"zh":"这是一个可以协商的要求。","en":"This request is open to negotiation.","category":"direction"},{"id":227,"zh":"不合适的方式可以停止。","en":"You can stop using an approach that does not fit.","category":"direction"},{"id":228,"zh":"如果只是怕被评价，仍然可以尝试。","en":"If judgment is your only fear, you can still try.","category":"direction"},{"id":229,"zh":"让真正参与的人一起决定。","en":"Let the people involved decide together.","category":"direction"},{"id":230,"zh":"暂时不要增加新的负担。","en":"Do not take on another burden for now.","category":"direction"},{"id":231,"zh":"你可以选择不参与这场比较。","en":"You can choose to leave this comparison behind.","category":"direction"},{"id":232,"zh":"支持已经足够时，就开始吧。","en":"Begin when you have enough support.","category":"direction"},{"id":233,"zh":"需要一再越界的关系，应当拉开距离。","en":"Create distance when a relationship repeatedly crosses your boundaries.","category":"direction"},{"id":234,"zh":"先选与你的主要目标一致的。","en":"Choose what serves your main goal first.","category":"direction"},{"id":235,"zh":"这次不必追求最特别的答案。","en":"You do not need the most unusual answer this time.","category":"direction"},{"id":236,"zh":"能坦然说明的决定，更值得考虑。","en":"Give more weight to a decision you can explain openly.","category":"direction"},{"id":237,"zh":"如果代价不断增加，就重新评估。","en":"Reassess if the cost keeps growing.","category":"direction"},{"id":238,"zh":"你可以只答应其中一部分。","en":"You can agree to only part of it.","category":"direction"},{"id":239,"zh":"先把这一项从清单上划掉。","en":"Cross this item off the list for now.","category":"direction"},{"id":240,"zh":"这里需要一个明确的答复。","en":"This needs a clear answer.","category":"direction"},{"id":241,"zh":"如果已有更好的安排，就婉拒。","en":"Decline politely if you already have a better plan.","category":"direction"},{"id":242,"zh":"把精力交给能够回应的地方。","en":"Give your energy where it can meet a response.","category":"direction"},{"id":243,"zh":"可以改变主意，但要及时说明。","en":"You can change your mind; communicate it promptly.","category":"direction"},{"id":244,"zh":"不要仅凭熟悉就留下。","en":"Do not stay solely because it is familiar.","category":"direction"},{"id":245,"zh":"在尊重彼此的前提下，坚持你的选择。","en":"Stand by your choice while respecting each other.","category":"direction"},{"id":246,"zh":"这件事值得完成，不必做到完美。","en":"This is worth finishing without making it perfect.","category":"direction"},{"id":247,"zh":"如果一切都要靠你撑着，就减轻一些。","en":"If everything depends on you, lighten the load.","category":"direction"},{"id":248,"zh":"你可以把最终决定留给自己。","en":"You can keep the final decision for yourself.","category":"direction"},{"id":249,"zh":"先选能保留余地的做法。","en":"Choose an approach that leaves some room to adjust.","category":"direction"},{"id":250,"zh":"当理由已经充分，就允许自己确定下来。","en":"When your reasons are enough, allow yourself to decide.","category":"direction"},{"id":251,"zh":"把没说清的话补完整。","en":"Finish saying what you left unclear.","category":"relationships"},{"id":252,"zh":"先听完，再准备你的回答。","en":"Hear them out before preparing your reply.","category":"relationships"},{"id":253,"zh":"这句话适合当面说。","en":"This deserves a face-to-face conversation.","category":"relationships"},{"id":254,"zh":"不必替对方猜出所有意思。","en":"You need not decode every hidden meaning.","category":"relationships"},{"id":255,"zh":"别人交给你的秘密，值得认真保管。","en":"Treat a secret entrusted to you with care.","category":"relationships"},{"id":256,"zh":"留一点空间给不同意见。","en":"Leave room for a different opinion.","category":"relationships"},{"id":257,"zh":"温和也可以很坚定。","en":"Gentle words can carry firm boundaries.","category":"relationships"},{"id":258,"zh":"对方需要的可能只是陪伴。","en":"They may simply want your company.","category":"relationships"},{"id":259,"zh":"先问一句：你想听建议吗？","en":"Ask first: would you like advice?","category":"relationships"},{"id":260,"zh":"把责备换成你的真实感受。","en":"Describe your feelings instead of assigning blame.","category":"relationships"},{"id":261,"zh":"这件事需要双方都点头。","en":"This needs a yes from both sides.","category":"relationships"},{"id":262,"zh":"回应之前，先确认自己听懂了。","en":"Check your understanding before you respond.","category":"relationships"},{"id":263,"zh":"一次坦白比反复试探更清楚。","en":"One honest conversation beats repeated hints.","category":"relationships"},{"id":264,"zh":"不要用沉默替自己谈条件。","en":"Do not leave silence to negotiate for you.","category":"relationships"},{"id":265,"zh":"关心可以从记住一件小事开始。","en":"Care can begin with remembering one small detail.","category":"relationships"},{"id":266,"zh":"给这段对话一个安静的地方。","en":"Find a quiet place for this conversation.","category":"relationships"},{"id":267,"zh":"感谢值得说出口。","en":"Let your gratitude be heard.","category":"relationships"},{"id":268,"zh":"对方的迟疑不一定与你有关。","en":"Their hesitation may have nothing to do with you.","category":"relationships"},{"id":269,"zh":"可以理解，也可以不接受。","en":"You can understand something without accepting it.","category":"relationships"},{"id":270,"zh":"说出你能做到的范围。","en":"Be clear about what you can offer.","category":"relationships"},{"id":271,"zh":"先约一个双方都方便的时间。","en":"Choose a time that works for both of you.","category":"relationships"},{"id":272,"zh":"别让一次误会替关系下结论。","en":"One misunderstanding need not define a relationship.","category":"relationships"},{"id":273,"zh":"问问对方最在意哪一部分。","en":"Ask which part matters most to them.","category":"relationships"},{"id":274,"zh":"把玩笑停在双方都舒服的地方。","en":"Keep the joke comfortable for both of you.","category":"relationships"},{"id":275,"zh":"这次先不替别人做决定。","en":"Leave this decision to the person concerned.","category":"relationships"},{"id":276,"zh":"认真对待那个小小的不舒服。","en":"Take that small discomfort seriously.","category":"relationships"},{"id":277,"zh":"亲近的人也可以有不同的爱好。","en":"People close to you can enjoy different things.","category":"relationships"},{"id":278,"zh":"亲近不等于随时待命。","en":"Being close does not mean always being available.","category":"relationships"},{"id":279,"zh":"把期待从心里搬到对话里。","en":"Bring your expectations into the conversation.","category":"relationships"},{"id":280,"zh":"给对方一个澄清的机会。","en":"Give them a chance to clarify.","category":"relationships"},{"id":281,"zh":"你的拒绝不需要层层包装。","en":"Your refusal does not need elaborate wrapping.","category":"relationships"},{"id":282,"zh":"先问清楚，再提供帮助。","en":"Ask what is needed before offering help.","category":"relationships"},{"id":283,"zh":"别把所有体谅都留给别人。","en":"Save some consideration for yourself.","category":"relationships"},{"id":284,"zh":"允许两个人的节奏不同。","en":"Allow each person to move at their own pace.","category":"relationships"},{"id":285,"zh":"分享感受时，少替别人下定义。","en":"Share your feelings without defining the other person.","category":"relationships"},{"id":286,"zh":"你可以重新商量旧的约定。","en":"You can renegotiate an old agreement.","category":"relationships"},{"id":287,"zh":"别把对方的脆弱变成争执的武器。","en":"Do not turn someone's vulnerability into a weapon during an argument.","category":"relationships"},{"id":288,"zh":"别急着把分歧变成输赢。","en":"A disagreement need not become a contest.","category":"relationships"},{"id":289,"zh":"把道歉说清楚，把改变做出来。","en":"Make your apology clear and your changes visible.","category":"relationships"},{"id":290,"zh":"今天适合问候那个想到的人。","en":"Reach out to someone on your mind today.","category":"relationships"},{"id":291,"zh":"给新认识的人一点观察时间。","en":"Take time to get to know someone new.","category":"relationships"},{"id":292,"zh":"聊得热络，不等于已经彼此了解。","en":"Lively conversation does not mean you already know each other well.","category":"relationships"},{"id":293,"zh":"分享彼此的好消息，也是一种靠近。","en":"Sharing good news is another way to grow closer.","category":"relationships"},{"id":294,"zh":"一句直接的询问能省去许多猜测。","en":"One direct question can save much guesswork.","category":"relationships"},{"id":295,"zh":"别在疲惫时解决所有分歧。","en":"Do not settle every disagreement while exhausted.","category":"relationships"},{"id":296,"zh":"在解释之前，先承认对方的感受。","en":"Acknowledge their feelings before explaining your side.","category":"relationships"},{"id":297,"zh":"把重要的人放进日程里。","en":"Make room in your calendar for people who matter.","category":"relationships"},{"id":298,"zh":"有些亲近来自一起做件小事。","en":"Sometimes closeness grows through a small shared task.","category":"relationships"},{"id":299,"zh":"不想谈的部分，可以暂时保留。","en":"You can keep some things private for now.","category":"relationships"},{"id":300,"zh":"询问比审问更容易靠近真相。","en":"Curiosity gets closer to the truth than interrogation.","category":"relationships"},{"id":301,"zh":"这件事不适合隔着别人传话。","en":"Speak directly instead of through someone else.","category":"relationships"},{"id":302,"zh":"先分清对方是在求助还是倾诉。","en":"Notice whether they want help or a listening ear.","category":"relationships"},{"id":303,"zh":"别把客气当作已经答应。","en":"Politeness is not necessarily agreement.","category":"relationships"},{"id":304,"zh":"尊重那个与你不同的答案。","en":"Respect the answer that differs from yours.","category":"relationships"},{"id":305,"zh":"你不必担任每个人的调解员。","en":"You do not have to mediate every dispute.","category":"relationships"},{"id":306,"zh":"说清底线，也给出可行的选择。","en":"State your boundary and offer workable options.","category":"relationships"},{"id":307,"zh":"关系也需要留白。","en":"Relationships need breathing room too.","category":"relationships"},{"id":308,"zh":"把这次的具体事情单独谈清楚。","en":"Discuss this particular incident on its own.","category":"relationships"},{"id":309,"zh":"愿意倾听，不代表必须赞同。","en":"Listening does not require agreement.","category":"relationships"},{"id":310,"zh":"在信任之前，允许自己慢一点。","en":"Allow yourself time before placing your trust.","category":"relationships"},{"id":311,"zh":"先照顾好对话里的语气。","en":"Start by attending to the tone of the conversation.","category":"relationships"},{"id":312,"zh":"把赞美落在具体的细节上。","en":"Make your compliment specific.","category":"relationships"},{"id":313,"zh":"别让比较替你评价身边的人。","en":"Do not let comparisons judge the people around you.","category":"relationships"},{"id":314,"zh":"这份邀请可以不带任何压力。","en":"Let this invitation come without pressure.","category":"relationships"},{"id":315,"zh":"有人退出，也可以好好告别。","en":"When someone leaves, a thoughtful goodbye is still possible.","category":"relationships"},{"id":316,"zh":"别用礼物代替该有的道歉。","en":"Do not use a gift in place of an apology.","category":"relationships"},{"id":317,"zh":"共同的规则值得一起制定。","en":"Make shared rules together.","category":"relationships"},{"id":318,"zh":"把你的需要与要求分开看看。","en":"Look separately at your needs and your demands.","category":"relationships"},{"id":319,"zh":"一次不合拍，可以先调整方式。","en":"When you are out of sync, try a different approach.","category":"relationships"},{"id":320,"zh":"对承诺保持清醒，对人保持温度。","en":"Be thoughtful about promises and warm toward people.","category":"relationships"},{"id":321,"zh":"不必替别人的情绪负全责。","en":"You are not solely responsible for another person's feelings.","category":"relationships"},{"id":322,"zh":"把关心表达成对方听得懂的样子。","en":"Express care in a way they can recognize.","category":"relationships"},{"id":323,"zh":"先确认这件事是否由你来开口。","en":"Check whether this is yours to bring up.","category":"relationships"},{"id":324,"zh":"给和解留门，不必一直守在门口。","en":"Leave room for reconciliation without waiting there forever.","category":"relationships"},{"id":325,"zh":"你可以喜欢一个人，也保留自己。","en":"You can care for someone and remain yourself.","category":"relationships"},{"id":326,"zh":"先把肩膀放松一点。","en":"Let your shoulders soften a little.","category":"letting_go"},{"id":327,"zh":"今天可以只完成最必要的事。","en":"Today, doing the essentials can be enough.","category":"letting_go"},{"id":328,"zh":"你不必喜欢每一张自己的照片。","en":"You do not have to like every photograph of yourself.","category":"letting_go"},{"id":329,"zh":"不是所有遗憾都需要补救。","en":"Not every regret needs repairing.","category":"letting_go"},{"id":330,"zh":"给自己一个不计成绩的下午。","en":"Give yourself an afternoon without keeping score.","category":"letting_go"},{"id":331,"zh":"那段话不必在脑中重播。","en":"You do not have to replay those words.","category":"letting_go"},{"id":332,"zh":"收好经验，放下自责。","en":"Keep the lesson; set down the blame.","category":"letting_go"},{"id":333,"zh":"你可以停止解释一个旧决定。","en":"You can stop explaining an old decision.","category":"letting_go"},{"id":334,"zh":"先吃好这一顿饭。","en":"Give this meal your full attention.","category":"letting_go"},{"id":335,"zh":"把休息从奖励改成日常。","en":"Make rest a routine instead of a reward.","category":"letting_go"},{"id":336,"zh":"给今天留一个柔软的结尾。","en":"Give today a gentle ending.","category":"letting_go"},{"id":337,"zh":"允许这件事留下一个句号。","en":"Allow this matter to reach a full stop.","category":"letting_go"},{"id":338,"zh":"不用把每个空档都填满。","en":"You do not need to fill every gap.","category":"letting_go"},{"id":339,"zh":"暂时做不到，也可以诚实承认。","en":"You can honestly admit that you cannot manage it yet.","category":"letting_go"},{"id":340,"zh":"把心里的清单缩短一些。","en":"Shorten the list you carry in your mind.","category":"letting_go"},{"id":341,"zh":"去窗边站一会儿。","en":"Spend a moment by the window.","category":"letting_go"},{"id":342,"zh":"先换上让你舒服的衣服。","en":"Put on something comfortable first.","category":"letting_go"},{"id":343,"zh":"别让昨天的失误占满今天。","en":"Do not let yesterday's mistake fill today.","category":"letting_go"},{"id":344,"zh":"独处的时光，不必过给谁看。","en":"Your time alone does not need an audience.","category":"letting_go"},{"id":345,"zh":"你可以怀念，却不必返回。","en":"You can miss it without going back.","category":"letting_go"},{"id":346,"zh":"把那件不再需要的东西收起来。","en":"Put away the thing you no longer need.","category":"letting_go"},{"id":347,"zh":"不舒服的时候，不必装得轻松。","en":"You need not appear carefree when you are uncomfortable.","category":"letting_go"},{"id":348,"zh":"慢一点，让心情跟上脚步。","en":"Slow down and let your feelings catch up.","category":"letting_go"},{"id":349,"zh":"允许快乐暂时没有用处。","en":"Joy does not have to serve another purpose.","category":"letting_go"},{"id":350,"zh":"不是所有美好都需要拍下来。","en":"Not every lovely moment needs a photograph.","category":"letting_go"},{"id":351,"zh":"给自己和给朋友一样的耐心。","en":"Offer yourself the patience you give a friend.","category":"letting_go"},{"id":352,"zh":"先结束这轮无休止的比较。","en":"Step out of this round of endless comparison.","category":"letting_go"},{"id":353,"zh":"不必把难过整理得很漂亮。","en":"Your sadness does not need to look tidy.","category":"letting_go"},{"id":354,"zh":"这份责任可以找人一起分担。","en":"Find someone to share this responsibility.","category":"letting_go"},{"id":355,"zh":"放下，不一定要有隆重的告别。","en":"Letting go does not require a grand goodbye.","category":"letting_go"},{"id":356,"zh":"你可以为已经尽力的自己停一停。","en":"Pause for the version of you that already tried.","category":"letting_go"},{"id":357,"zh":"失去兴趣，不代表从前的喜欢是假的。","en":"Losing interest does not make your earlier enjoyment false.","category":"letting_go"},{"id":358,"zh":"让房间先安静下来。","en":"Let the room grow quiet first.","category":"letting_go"},{"id":359,"zh":"暂时没有答案，也能过好今天。","en":"You can live today without having the answer yet.","category":"letting_go"},{"id":360,"zh":"那一次尴尬不必成为你的标签。","en":"That awkward moment need not become your label.","category":"letting_go"},{"id":361,"zh":"先允许自己说一句累了。","en":"Allow yourself to say you are tired.","category":"letting_go"},{"id":362,"zh":"把不属于你的评价放回原处。","en":"Leave opinions that are not yours where they belong.","category":"letting_go"},{"id":363,"zh":"别急着给每一种情绪找原因。","en":"You need not explain every feeling immediately.","category":"letting_go"},{"id":364,"zh":"给旧计划一次正式的结束。","en":"Bring the old plan to a deliberate close.","category":"letting_go"},{"id":365,"zh":"不必赶着证明你已经释怀。","en":"There is no deadline for proving you have moved on.","category":"letting_go"},{"id":366,"zh":"清空一小块桌面就好。","en":"Clearing one small corner of your desk is enough.","category":"letting_go"},{"id":367,"zh":"今天可以少看一点外界的声音。","en":"Take in a little less outside noise today.","category":"letting_go"},{"id":368,"zh":"放过那个当时还不懂的自己。","en":"Be kind to the self who did not know then.","category":"letting_go"},{"id":369,"zh":"有些东西，留在回忆里就够了。","en":"Some things can simply remain in memory.","category":"letting_go"},{"id":370,"zh":"别把每次休息都变成反省。","en":"Not every pause needs to become self-examination.","category":"letting_go"},{"id":371,"zh":"先让身体换一个舒服的姿势。","en":"Find a more comfortable position first.","category":"letting_go"},{"id":372,"zh":"不需要从每段经历里提炼意义。","en":"You need not extract meaning from every experience.","category":"letting_go"},{"id":373,"zh":"给自己留一点不用解释的时间。","en":"Keep some time you do not have to account for.","category":"letting_go"},{"id":374,"zh":"今天的步子小一些也无妨。","en":"Today's steps can be smaller.","category":"letting_go"},{"id":375,"zh":"停止追问一个已经说完的故事。","en":"Stop questioning a story that has already ended.","category":"letting_go"},{"id":376,"zh":"把那句苛刻的话改写得公平些。","en":"Rewrite that harsh thought more fairly.","category":"letting_go"},{"id":377,"zh":"允许自己重新喜欢简单的事情。","en":"Let yourself enjoy simple things again.","category":"letting_go"},{"id":378,"zh":"先离开让你反复纠结的画面。","en":"Step away from the scene you keep dwelling on.","category":"letting_go"},{"id":379,"zh":"不用一次整理好整个生活。","en":"You need not put your whole life in order at once.","category":"letting_go"},{"id":380,"zh":"借一点时间给什么也不做。","en":"Set aside some time to do nothing.","category":"letting_go"},{"id":381,"zh":"你可以暂停，但不必宣布失败。","en":"You can pause without declaring defeat.","category":"letting_go"},{"id":382,"zh":"这次不必把所有原因都追到底。","en":"You need not trace every cause this time.","category":"letting_go"},{"id":383,"zh":"珍惜曾经，也接受如今。","en":"Value what was and acknowledge what is.","category":"letting_go"},{"id":384,"zh":"把今天已经完成的事数一数。","en":"Count what you have already done today.","category":"letting_go"},{"id":385,"zh":"别替未发生的事情提前疲惫。","en":"Do not exhaust yourself over what has not happened.","category":"letting_go"},{"id":386,"zh":"走一小段路，再回来看看。","en":"Take a short walk, then look again.","category":"letting_go"},{"id":387,"zh":"给那份失落留个位置就好。","en":"Simply make some room for the disappointment.","category":"letting_go"},{"id":388,"zh":"允许一个普通的日子保持普通。","en":"Let an ordinary day stay ordinary.","category":"letting_go"},{"id":389,"zh":"暂时放低标准，保留真正重要的。","en":"Lower the standard for now; keep what matters.","category":"letting_go"},{"id":390,"zh":"把自己从必须完美里领出来。","en":"Lead yourself away from the demand for perfection.","category":"letting_go"},{"id":391,"zh":"先弄清你究竟想改变什么。","en":"First, name what you actually want to change.","category":"perspective"},{"id":392,"zh":"把别人的期待暂时拿开。","en":"Set other people's expectations aside for a moment.","category":"perspective"},{"id":393,"zh":"这个选择值得用自己的尺度衡量。","en":"Measure this choice by your own standards.","category":"perspective"},{"id":394,"zh":"先分清喜欢与羡慕。","en":"Distinguish what you like from what you envy.","category":"perspective"},{"id":395,"zh":"选择越多，越需要知道自己不想要什么。","en":"More options make knowing what you do not want more important.","category":"perspective"},{"id":396,"zh":"把目标说得更具体。","en":"Describe the goal more precisely.","category":"perspective"},{"id":397,"zh":"最显眼的部分未必最重要。","en":"The most visible part may not matter most.","category":"perspective"},{"id":398,"zh":"再想想你愿意为此放弃什么。","en":"Consider what you are willing to give up for this.","category":"perspective"},{"id":399,"zh":"容易得到的东西，也值得认真挑选。","en":"Even readily available things deserve a thoughtful choice.","category":"perspective"},{"id":400,"zh":"熟练有时会遮住新的可能。","en":"Being skilled at one thing can obscure new possibilities.","category":"perspective"},{"id":401,"zh":"意外得到的机会，也要看是否合适。","en":"Even an unexpected opportunity needs to fit.","category":"perspective"},{"id":402,"zh":"先问这份答案是写给谁的。","en":"First, ask who this answer was written for.","category":"perspective"},{"id":403,"zh":"选那个你愿意继续投入的方向。","en":"Choose the direction you are willing to keep working on.","category":"perspective"},{"id":404,"zh":"这个答案需要你的生活来验证。","en":"Let your own experience test this answer.","category":"perspective"},{"id":405,"zh":"评价互相矛盾时，看看各自重视什么。","en":"When opinions conflict, examine what each one values.","category":"perspective"},{"id":406,"zh":"你向往的自由里，也包含责任。","en":"The freedom you want comes with responsibilities too.","category":"perspective"},{"id":407,"zh":"问问自己：没有观众，还想做吗？","en":"Would you still want this without an audience?","category":"perspective"},{"id":408,"zh":"把习惯性的答应停下来看看。","en":"Pause before giving your habitual yes.","category":"perspective"},{"id":409,"zh":"热爱可以有很多种，不必只选一种。","en":"You can have several passions without choosing just one.","category":"perspective"},{"id":410,"zh":"先区分紧急和重要。","en":"Separate what is urgent from what matters.","category":"perspective"},{"id":411,"zh":"现在的你可以选择新的标准。","en":"You can choose different standards now.","category":"perspective"},{"id":412,"zh":"把问题从为什么换成接下来怎么做。","en":"Move from asking why to asking what comes next.","category":"perspective"},{"id":413,"zh":"别只凭最难的那一天评价全部。","en":"Do not judge everything by its hardest day.","category":"perspective"},{"id":414,"zh":"看看有没有被忽略的第三种选择。","en":"Look for a third option you may have missed.","category":"perspective"},{"id":415,"zh":"有用和喜欢，可以分别考虑。","en":"Consider usefulness and enjoyment separately.","category":"perspective"},{"id":416,"zh":"先想清楚什么结果已经足够。","en":"Decide what outcome would be enough.","category":"perspective"},{"id":417,"zh":"不是每一种兴趣都需要变成工作。","en":"Not every interest needs to become a job.","category":"perspective"},{"id":418,"zh":"把想拥有的东西换成想过的日子。","en":"Think about the life you want, beyond what you want to own.","category":"perspective"},{"id":419,"zh":"做得好与想继续，是两回事。","en":"Doing something well and wanting to continue are different things.","category":"perspective"},{"id":420,"zh":"把赢得认可与获得满足分开。","en":"Distinguish winning approval from finding satisfaction.","category":"perspective"},{"id":421,"zh":"看看这个决定是否出于害怕错过。","en":"Check whether fear of missing out is deciding for you.","category":"perspective"},{"id":422,"zh":"有些能力，需要合适的场景才显出来。","en":"Some abilities only become visible in the right setting.","category":"perspective"},{"id":423,"zh":"不熟悉不等于不适合。","en":"Unfamiliar does not mean unsuitable.","category":"perspective"},{"id":424,"zh":"你可以只对眼前这一步负责。","en":"You can take responsibility for just this next step.","category":"perspective"},{"id":425,"zh":"别用理想状态要求每一天。","en":"Do not demand ideal conditions from every day.","category":"perspective"},{"id":426,"zh":"先确定你想保留什么。","en":"Decide what you want to preserve first.","category":"perspective"},{"id":427,"zh":"这个目标也许需要换一种实现方式。","en":"This goal may need a different approach.","category":"perspective"},{"id":428,"zh":"看清代价，再谈值不值得。","en":"Understand the cost before deciding whether it is worthwhile.","category":"perspective"},{"id":429,"zh":"把成功定义得更贴近自己。","en":"Define success in terms that fit you better.","category":"perspective"},{"id":430,"zh":"并非每个建议都适合你的处境。","en":"Not every suggestion fits your circumstances.","category":"perspective"},{"id":431,"zh":"问问自己在维护什么。","en":"Ask what you are trying to protect.","category":"perspective"},{"id":432,"zh":"可以借鉴别人的路，不必复制终点。","en":"Learn from another path without adopting its destination.","category":"perspective"},{"id":433,"zh":"留意这个目标是谁最先提出的。","en":"Notice who first proposed this goal.","category":"perspective"},{"id":434,"zh":"让实际体验修正你的想象。","en":"Let experience revise what you imagined.","category":"perspective"},{"id":435,"zh":"没有被看见的努力，也参与了结果。","en":"Unseen effort also contributes to the result.","category":"perspective"},{"id":436,"zh":"别把不习惯误认成做错了。","en":"Discomfort with something new does not necessarily mean it is wrong.","category":"perspective"},{"id":437,"zh":"把有限的精力留给真正想做的事。","en":"Save your limited energy for what you truly want to do.","category":"perspective"},{"id":438,"zh":"如果重新开始，你还会选它吗？","en":"If you started again, would you still choose this?","category":"perspective"},{"id":439,"zh":"一个小证据比许多猜想更有用。","en":"One small piece of evidence can outweigh many guesses.","category":"perspective"},{"id":440,"zh":"先试着准确描述现状。","en":"Try describing the present situation accurately first.","category":"perspective"},{"id":441,"zh":"你想要的也许比你列出的更简单。","en":"What you want may be simpler than your list suggests.","category":"perspective"},{"id":442,"zh":"当手段成了目标，就该重新想一想。","en":"Reconsider when the means have become the goal.","category":"perspective"},{"id":443,"zh":"别让一次称赞决定整个方向。","en":"Do not let one compliment set your entire direction.","category":"perspective"},{"id":444,"zh":"你可以承认自己并不喜欢它。","en":"You can admit that you do not like it.","category":"perspective"},{"id":445,"zh":"有些选择只需要合适，不需要耀眼。","en":"Some choices only need to fit, not impress.","category":"perspective"},{"id":446,"zh":"现在缺的是信息，还是勇气？","en":"Are you missing information or courage?","category":"perspective"},{"id":447,"zh":"先给这件事一个合理的边界。","en":"Give this undertaking reasonable limits first.","category":"perspective"},{"id":448,"zh":"公平不一定是每人分得一样。","en":"Fairness does not always mean everyone gets the same.","category":"perspective"},{"id":449,"zh":"问问自己是否愿意承担日常部分。","en":"Ask whether you are willing to do the everyday work.","category":"perspective"},{"id":450,"zh":"换一个距离，可能看得更清楚。","en":"A little distance may bring a clearer view.","category":"perspective"},{"id":451,"zh":"你不必沿用最初的理由。","en":"You do not have to keep your original reason.","category":"perspective"},{"id":452,"zh":"看看哪些条件其实已经改变。","en":"Notice which conditions have already changed.","category":"perspective"},{"id":453,"zh":"诚实的选择，有时并不讨巧。","en":"An honest choice is not always a popular one.","category":"perspective"},{"id":454,"zh":"别把暂时的排名当成最终的位置。","en":"A temporary ranking is not your final place.","category":"perspective"},{"id":455,"zh":"把选择写下来，看看哪项最诚实。","en":"Write down your options and notice which feels most honest.","category":"perspective"},{"id":456,"zh":"可以保留疑问，同时继续观察。","en":"You can keep your questions open and keep observing.","category":"perspective"},{"id":457,"zh":"眼前的不方便与长期的不合适要分开。","en":"Distinguish temporary inconvenience from a lasting mismatch.","category":"perspective"},{"id":458,"zh":"别让惯例替你完成思考。","en":"Do not let convention do your thinking for you.","category":"perspective"},{"id":459,"zh":"先确定什么是你不愿交换的。","en":"Identify what you are unwilling to trade away.","category":"perspective"},{"id":460,"zh":"回到最初吸引你的那个细节。","en":"Return to the detail that first drew you in.","category":"perspective"},{"id":461,"zh":"如果给这件事起个新名字呢？","en":"What if you gave this a new name?","category":"open_prompts"},{"id":462,"zh":"先把问题倒过来读一遍。","en":"Try reading the question the other way around.","category":"open_prompts"},{"id":463,"zh":"给犹豫画一张小地图。","en":"Draw a little map of your hesitation.","category":"open_prompts"},{"id":464,"zh":"用三个词形容你想要的感觉。","en":"Describe the feeling you want in three words.","category":"open_prompts"},{"id":465,"zh":"也许可以从最不起眼的一角开始。","en":"Perhaps start in the least noticeable corner.","category":"open_prompts"},{"id":466,"zh":"如果答案是一种颜色，会是什么？","en":"If the answer were a color, what would it be?","category":"open_prompts"},{"id":467,"zh":"把复杂的事讲给一只想象中的猫。","en":"Explain the complicated part to an imaginary cat.","category":"open_prompts"},{"id":468,"zh":"试着只保留问题里最重要的动词。","en":"Keep only the most important verb in your question.","category":"open_prompts"},{"id":469,"zh":"给今天加一个小小的意外。","en":"Add one small surprise to today.","category":"open_prompts"},{"id":470,"zh":"把最不可能的选项也写进草稿。","en":"Give even the most unlikely option a place in your draft.","category":"open_prompts"},{"id":471,"zh":"如果不用证明什么，你会怎样选？","en":"How would you choose with nothing to prove?","category":"open_prompts"},{"id":472,"zh":"换个座位，再想一遍。","en":"Change seats and think again.","category":"open_prompts"},{"id":473,"zh":"先找一个让你好奇的细节。","en":"Find one detail that makes you curious.","category":"open_prompts"},{"id":474,"zh":"假如给朋友出主意，你会说什么？","en":"What would you tell a friend in this position?","category":"open_prompts"},{"id":475,"zh":"给严肃的问题留一点幽默。","en":"Leave a little humor in this serious question.","category":"open_prompts"},{"id":476,"zh":"试着写出一个不那么标准的答案。","en":"Try writing an answer that is less conventional.","category":"open_prompts"},{"id":477,"zh":"如果只能做一半，你会保留哪半？","en":"If you could do only half, which half would you keep?","category":"open_prompts"},{"id":478,"zh":"如果这件事有说明书，第一页写什么？","en":"If this came with instructions, what would the first page say?","category":"open_prompts"},{"id":479,"zh":"你遗漏的线索会不会就在标题里？","en":"Could the missing clue be in the title?","category":"open_prompts"},{"id":480,"zh":"给这个念头一张草稿纸。","en":"Give this thought a sheet of scrap paper.","category":"open_prompts"},{"id":481,"zh":"把下一步想成一扇门。","en":"Imagine the next step as a door.","category":"open_prompts"},{"id":482,"zh":"试着用一个物件代表此刻的心情。","en":"Choose an object to represent how you feel right now.","category":"open_prompts"},{"id":483,"zh":"如果删掉必须，问题会变成什么？","en":"How does the question change without the word must?","category":"open_prompts"},{"id":484,"zh":"先写一个大胆版本，再慢慢修改。","en":"Write a bold version first, then revise it.","category":"open_prompts"},{"id":485,"zh":"为那个还没成形的想法留个名字。","en":"Give the unfinished idea a name to grow into.","category":"open_prompts"},{"id":486,"zh":"别急，先看看书页的空白。","en":"Pause and notice the blank space on the page.","category":"open_prompts"},{"id":487,"zh":"把答案藏进明天的一件小事里。","en":"Put your answer into one small action tomorrow.","category":"open_prompts"},{"id":488,"zh":"如果这是故事中间，你想怎样续写？","en":"If this were the middle, how would you continue the story?","category":"open_prompts"},{"id":489,"zh":"试着把难题说得像天气一样平常。","en":"Describe the difficulty as plainly as the weather.","category":"open_prompts"},{"id":490,"zh":"你会给此刻配什么音乐？","en":"What music would you choose for this moment?","category":"open_prompts"},{"id":491,"zh":"给平常的步骤加一点新花样。","en":"Add a small twist to an ordinary step.","category":"open_prompts"},{"id":492,"zh":"先为一个很小的可能性留门。","en":"Leave the door open for one tiny possibility.","category":"open_prompts"},{"id":493,"zh":"如果不能赶时间，你会怎样安排？","en":"How would you plan this if rushing were impossible?","category":"open_prompts"},{"id":494,"zh":"把这个问题画成两个圆。","en":"Draw this question as two circles.","category":"open_prompts"},{"id":495,"zh":"最想删掉的那个词，值得看看。","en":"Look closely at the word you most want to delete.","category":"open_prompts"},{"id":496,"zh":"给答案留一点转弯的余地。","en":"Leave the answer a little room to turn.","category":"open_prompts"},{"id":497,"zh":"今天先收集线索，不急着结案。","en":"Collect clues today; the case can stay open.","category":"open_prompts"},{"id":498,"zh":"问一个你平时不会问的小问题。","en":"Ask a small question you would not usually ask.","category":"open_prompts"},{"id":499,"zh":"把想法念出声，听听它的样子。","en":"Say the idea aloud and hear how it sounds.","category":"open_prompts"},{"id":500,"zh":"这一页结束后，你想先做什么？","en":"What would you like to do after this page?","category":"open_prompts"}];
